import { cn } from '@/lib/utils/cn';

interface SectionProps extends React.HTMLAttributes<HTMLElement> {
  children: React.ReactNode;
  variant?: 'default' | 'muted' | 'accent' | 'primary';
  withPattern?: boolean;
  containerClass?: string;
}

export function Section({ 
  children, 
  className, 
  variant = 'default', 
  withPattern = false,
  containerClass,
  ...props 
}: SectionProps) {
  
  const variants = {
    default: "bg-background",
    muted: "bg-muted/50", // Clean, consistent muted background
    accent: "bg-accent/5",
    primary: "bg-primary text-primary-foreground",
  };

  return (
    <section 
      className={cn(
        "section-wrapper", // Uses our new utility class
        variants[variant],
        className
      )} 
      {...props}
    >
      {withPattern && variant !== 'primary' && (
        <div className="absolute inset-0 bg-grid-pattern opacity-[0.03] pointer-events-none" />
      )}
      
      <div className={cn("container-custom relative z-10", containerClass)}>
        {children}
      </div>
    </section>
  );
}
